goy(){return"N\u01b0\u1edbc \u0111i hay! Gi\u1edd t\u1edbi l\u01b0\u1ee3t m\xecnh. Hai b\xean l\u1ea7n l\u01b0\u1ee3t \u0111i, m\u1ed7i ng\u01b0\u1eddi m\u1ed9t n\u01b0\u1edbc."},
go8(){return"L\u1ea1i t\u1edbi b\u1ea1n. Ch\u1ecdn qu\xe2n n\xe0o c\xf3 \xf4 t\u1ed1i tr\u1ed1ng \u1edf ch\xe9o ph\xeda tr\u01b0\u1edbc."},
gmp(){return"Qu\xe2n \u0111\xf3 b\u1ecb k\u1eb9t: ph\xeda tr\u01b0\u1edbc kh\xf4ng c\xf2n \xf4 tr\u1ed1ng. Th\u1eed qu\xe2n kh\xe1c nh\xe9."},
gmM(){return"\u0110ang c\xf3 n\u01b0\u1edbc \u0103n, v\xe0 \u0103n qu\xe2n l\xe0 \u01b0u ti\xean! T\xecm c\xe1c qu\xe2n \u0111ang s\xe1ng."},
go9(){return"Tuy\u1ec7t! Ch\u1ea1m v\xe0o m\u1ed9t qu\xe2n \u0111\u1ec3 th\u1ea5y c\xe1c n\u01b0\u1edbc \u0111i. Qu\xe2n th\u01b0\u1eddng ch\u1ec9 \u0111\u01b0\u1ee3c \u0111i t\u1edbi."},
gpi(){return"Ch\u01b0a \u0111\xfang. L\xe0m theo b\xe0n tay nh\xe9!"},
goi(){return"\u0102n qu\xe2n th\xf4i! Qu\xe2n m\xecnh ngay tr\u01b0\u1edbc qu\xe2n b\u1ea1n v\xe0 \xf4 ph\xeda sau tr\u1ed1ng. Nh\u1ea3y qua n\xf3!"},
goj(){return"B\u1eaft \u0111\u01b0\u1ee3c! Qu\xe2n b\u1ecb nh\u1ea3y qua b\u1ecb \u0103n v\xe0 r\u1eddi kh\u1ecfi b\xe0n c\u1edd."},
goB(){return"Lu\u1eadt l\xe0m ai c\u0169ng b\u1ea5t ng\u1edd: n\u1ebfu \u0103n \u0111\u01b0\u1ee3c th\xec b\u1eaft bu\u1ed9c ph\u1ea3i \u0103n. Th\u1eed \u0111i qu\xe2n kia xem."},
goE(){return"Kh\xf4ng nh\xfac nh\xedch! \u0110ang c\xf3 n\u01b0\u1edbc \u0103n n\xean ph\u1ea3i \u0103n tr\u01b0\u1edbc. C\xe1c qu\xe2n b\u1eaft bu\u1ed9c \u0103n \u0111ang s\xe1ng l\xean."},
goD(){return"Gi\u1edd th\xec \u0103n \u0111i."},
goC(){return"Nh\u1edb nh\xe9: \u0103n qu\xe2n l\xe0 b\u1eaft bu\u1ed9c. Ng\u01b0\u1eddi ch\u01a1i gi\u1ecfi d\xf9ng lu\u1eadt n\xe0y \u0111\u1ec3 g\xe0i b\u1eaby!"},
goz(){return"Sau khi nh\u1ea3y, n\u1ebfu qu\xe2n c\xf2n nh\u1ea3y ti\u1ebfp \u0111\u01b0\u1ee3c th\xec \u0111i ti\u1ebfp trong c\xf9ng l\u01b0\u1ee3t. \u0102n c\u1ea3 ba!"},
goA(){return"Ba qu\xe2n trong m\u1ed9t n\u01b0\u1edbc! \u0102n li\xean ho\xe0n c\xf3 th\u1ec3 l\u1eadt ng\u01b0\u1ee3c v\xe1n c\u1edd."},
gol(){return"\u0110\u1ebfn \u0111\u01b0\u1ee3c h\xe0ng cu\u1ed1i c\u1ee7a m\xecnh l\xe0 qu\xe2n b\u1ea1n l\xean vua. B\u01b0\u1edbc l\xean h\xe0ng v\xe0ng n\xe0o!"},
goo(){return"Vua \u0111\xe3 l\xean ng\xf4i! L\xean vua l\xe0 h\u1ebft l\u01b0\u1ee3t, gi\u1edd t\u1edbi m\xecnh."},
gop(){return"\u0110\u1ec3 m\xecnh l\u1ebbn ra sau vua c\u1ee7a b\u1ea1n..."},
gom(){return"Qu\xe2n th\u01b0\u1eddng ch\u1ec9 \u0111i t\u1edbi, nh\u01b0ng vua \u0111i l\xf9i \u0111\u01b0\u1ee3c. \u0102n m\xecnh t\u1eeb ph\xeda sau \u0111i!"},
gon(){return"Vua \u0111i v\xe0 \u0103n \u0111\u01b0\u1ee3c c\u1ea3 b\u1ed1n h\u01b0\u1edbng. Gi\u1eef vua c\u1ea9n th\u1eadn nh\xe9!"},
gpd(){return"Mu\u1ed1n th\u1eafng, h\xe3y \u0103n h\u1ebft qu\xe2n c\u1ee7a m\xecnh. \u0102n qu\xe2n cu\u1ed1i c\xf9ng \u0111i!"},
gpf(){return"B\u1ea1n c\u0169ng th\u1eafng khi m\xecnh h\u1ebft n\u01b0\u1edbc \u0111i. Nh\u1ed1t qu\xe2n cu\u1ed1i c\u1ee7a m\xecnh l\u1ea1i!"},
gpg(){return"M\xecnh v\u1eabn c\xf2n \u0111i \u0111\u01b0\u1ee3c. T\xecm \xf4 l\xe0m m\xecnh b\u1ecb k\u1eb9t."},
gph(){return"M\xecnh b\u1ecb k\u1eb9t, b\u1ea1n th\u1eafng! Khi kh\xf4ng b\xean n\xe0o ti\u1ebfn tri\u1ec3n \u0111\u01b0\u1ee3c, v\xe1n c\u1edd h\xf2a."},
goK(){return"B\u1ea1n t\u1ef1 t\xecm ra r\u1ed3i. M\u1eb9o n\xe0y l\xe0 c\u1ee7a b\u1ea1n!"},
gnb(){return"Tr\u01b0\u1edbc m\u1ed7i n\u01b0\u1edbc, h\xe3y xem m\xecnh c\xf3 \u0103n \u0111\u01b0\u1ee3c kh\xf4ng. Xem chuy\u1ec7n g\xec x\u1ea3y ra n\u1ebfu b\u1ea1n \u0111i v\xe0o \u0111\xe2y."},
gn8(){return"Qu\xe2n b\u1ea1n d\u1eebng ngay tr\u01b0\u1edbc qu\xe2n m\xecnh, m\xe0 ph\xeda sau l\u1ea1i tr\u1ed1ng..."},
gnc(){return"\u1ed0i! Gi\u1edd t\xecm n\u01b0\u1edbc kh\xf4ng cho m\xecnh \u0103n kh\xf4ng nh\xe9."},
gnd(){return"Nh\xecn tr\u01b0\u1edbc khi \u0111i! \u0110i m\u1ed9t n\u01b0\u1edbc \u0111\u1ec3 m\xecnh kh\xf4ng c\xf3 g\xec \u0111\u1ec3 \u0103n."},
gna(){return"M\xecnh \u0111\u01b0\u1ee3c \u0103n kh\xf4ng! Ki\u1ec3m tra \xf4 ph\xeda sau tr\u01b0\u1edbc khi \u0111i nh\xe9."},
gn9(){return"An to\xe0n! Xem n\u01b0\u1edbc \u0103n c\u1ee7a \u0111\u1ed1i th\u1ee7 tr\u01b0\u1edbc l\xe0 th\xf3i quen c\u1ee7a ng\u01b0\u1eddi ch\u01a1i gi\u1ecfi."},
gnl(){return"\u0102n l\xe0 b\u1eaft bu\u1ed9c, n\xean b\u1ea1n \xe9p \u0111\u01b0\u1ee3c n\u01b0\u1edbc \u0111i c\u1ee7a m\xecnh. Th\xed m\u1ed9t qu\xe2n, v\xe0 c\xfa nh\u1ea3y c\u1ee7a m\xecnh s\u1ebd \u0111\xe1p \u0111\xfang ch\u1ed7 b\u1ea1n mu\u1ed1n."},
gnm(){return"T\xecm \u0111\xf2n: th\xed m\u1ed9t qu\xe2n \u0111\u1ec3 \u0103n l\u1ea1i nhi\u1ec1u h\u01a1n."},
gnk(){return"M\xecnh bu\u1ed9c ph\u1ea3i \u0103n. Lu\u1eadt m\xe0!"},
gnj(){return"Gi\u1edd s\u1eadp b\u1eaby: nh\u1ea3y \u0103n h\u1ebft nh\u1eefng g\xec c\xf3 th\u1ec3!"},
gni(){return"Kh\xf4ng c\xf3 \u0111\xf2n \u1edf \u0111\xf3. T\xecm qu\xe2n \u0111\u1ec3 th\xed m\u1edf ra n\u01b0\u1edbc \u0103n li\xean ho\xe0n."},
gnh(){return"Th\xed m\u1ed9t, \u0103n nhi\u1ec1u h\u01a1n! \u0110\xf3 g\u1ecdi l\xe0 m\u1ed9t \u0111\xf2n."},
gnU(){return"Qu\xe2n \u1edf h\xe0ng cu\u1ed1i c\u1ee7a m\xecnh canh h\xe0ng phong vua. D\u1ee5 n\xf3 \u0111i b\u1eb1ng m\u1ed9t qu\xe2n th\xed, r\u1ed3i lu\u1ed3n qua l\xean vua!"},
gnV(){return"\u0110\u1ed9t ph\xe1! Th\xed m\u1ed9t qu\xe2n \u0111\u1ec3 m\u1edf \u0111\u01b0\u1eddng t\u1edbi h\xe0ng cu\u1ed1i c\u1ee7a m\xecnh."},
